            SceneKit.Point(bots, "坡顶拐角", new Vector3(-20f, 2f, 8f), 225f, BotBehavior.Static, new Vector3(0f, 0f, 0f), 3f, true);
            SceneKit.Area(bots, "SiteSpawnArea", new Vector3(-13f, 6f, 19f), new Vector3(42f, 8f, 26f));
            SceneKit.PlayerRig rig = SceneKit.CreatePlayer(new Vector3(-14f, 0f, -40f), 0f, withTraining: true);
            var aimSpawn = new GameObject("AimModeSpawn").transform;
            aimSpawn.SetPositionAndRotation(new Vector3(-14f, 2f, 9f), Quaternion.Euler(0f, 0f, 0f));
            rig.Session.SetAimSpawn(aimSpawn);
            SceneKit.SaveScene(scene, SceneCatalog.SplitAScene);
        }
    }
}
